import sys

data = sys.stdin.buffer.read().splitlines()
n = int(data[0])
depth = 0
valid = True

for line in data[1:1 + n]:
    for char in line:
        if char == ord('{'):
            depth += 1
        elif char == ord('}'):
            depth -= 1
            if depth < 0:
                valid = False

print("S" if valid and depth == 0 else "N")
